import{c as a,Q as e,j as l,m as i}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"GetMatmulApiTiling","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetMatmulApiTiling","slug":"getmatmulapitiling"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetMatmulApiTiling.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetMatmulApiTiling.md"}'),s={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetMatmulApiTiling.md"};function n(r,t,d,p,o,m){return e(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="getmatmulapitiling" tabindex="-1">GetMatmulApiTiling <a class="header-anchor" href="#getmatmulapitiling" aria-label="Permalink to &quot;GetMatmulApiTiling&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>本接口用于在编译期间获取常量化的Matmul Tiling参数。</p><p>Matmul Tiling常量化功能为在编译期期间获取常量化的Matmul Tiling参数并进行算子编译，从而减少Scalar计算开销，提升算子整体性能。具体为，在获取<a href="./Matmul模板参数.html">Matmul模板</a>时，可以确定<a href="./MatmulConfig.html">MatmulConfig</a>的singleCore Shape（<a href="./MatmulConfig.html">MatmulConfig</a>中的singleCoreM/singleCoreN/singleCoreK）和Base Shape（<a href="./MatmulConfig.html">MatmulConfig</a>中的basicM/basicN/basicK）参数，或者只确定Base Shape参数；通过指定获取模板的接口中的singleCore Shape和Base Shape参数，或者只指定Base Shape参数，获取自定义模板；然后调用本接口，得到常量化的Matmul Tiling参数。</p><p>当在调用<a href="./MatmulConfig.html#li0460173613513">获取MatmulConfig模板的接口</a>时，只将(baseM, baseN, baseK)设置为常数值时，称为部分常量化，此时(singleCoreM, singleCoreN, singleCoreK)都保持默认值0，部分常量化场景在Kernel侧使用<a href="./REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>初始化Matmul对象时，仍需要使用Tiling；将(baseM, baseN, baseK, singleCoreM, singleCoreN, singleCoreK)都设置为常数值时，称为全量常量化，这时可以在<a href="./REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>的入参传递Tiling参数的位置，使用空指针替代。</p><p>经过上述部分常量化或全部常量化后，将得到带有常量化参数的MatmulConfig模板，然后使用本接口将Tiling参数常量化。本接口的返回值包含常量化的Matmul Tiling参数和MatmulConfig模板。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;class A_TYPE, class B_TYPE, class C_TYPE, class BIAS_TYPE&gt;</span></span>
<span class="line"><span>__aicore__ constexpr MatmulApiStaticTiling GetMatmulApiTiling(const MatmulConfig&amp; mmCFG, int32_t l1Size = Impl::L1_SIZE)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>A_TYPE</td><td>A矩阵类型信息，通过MatmulType来定义。</td></tr><tr><td>B_TYPE</td><td>B矩阵类型信息，通过MatmulType来定义。</td></tr><tr><td>C_TYPE</td><td>C矩阵类型信息，通过MatmulType来定义。</td></tr><tr><td>BIAS_TYPE</td><td>BIAS矩阵类型信息，通过MatmulType来定义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mmCFG</td><td>输入</td><td>获取的MatmulConfig模板。 对于Ascend 950PR/Ascend 950DT，支持常量化的为全部模板：Norm, IBShare, MDL模板。 对于Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持常量化的模板有：Norm, MDL模板。 对于Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持常量化的模板有：Norm, MDL模板。 对于Kirin X90，支持常量化的模板有：Norm, MDL模板。</td></tr><tr><td>l1Size</td><td>输入</td><td>可用的L1大小，默认值L1_SIZE。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p><a href="./Matmul模板参数.html#table7939847143412">MatmulApiStaticTiling</a></p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>入参mmCFG，在调用获取MatmulConfig模板的接口获取时，需要使用常数值指定(baseM, baseN, baseK)或者指定(baseM, baseN, baseK, singleCoreM, singleCoreN, singleCoreK)，并且指定的参数值需要和Tiling计算的值保持一致。</li><li>Batch Matmul场景支持全量常量化，但不支持使用空指针替代REGIST_MATMUL_OBJ的入参Tiling。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//定义Matmul对象</span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType; </span></span>
<span class="line"><span>// 这里CFG使用GetNormalConfig接口获取，并指定已知的singleshape信息和baseM,baseN,baseK，指定的数值跟运行时tiling保持一致</span></span>
<span class="line"><span>constexpr auto staticTiling = GetMatmulApiTiling&lt;aType, bType, cType, biasType&gt;(CFG, 524288); // 该示例L1 Buffer可用大小为512KB</span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, staticTiling &gt; mm;</span></span></code></pre></div>`,21)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
